        CfUtils.GetCf(AutoIds.IdSetting6183, "DreamAdventuresMainNodeVo")
        CfUtils.GetCf(AutoIds.IdSetting6184, "DreamAdventuresMainLinesVo")

        coroutine.yield()

        CfUtils.GetCf(AutoIds.IdSetting6191, "DreamAdventuresAllRewardsVo")
        CfUtils.GetCf(AutoIds.IdSetting6190, "DreamAdventuresPersonalRewardsVo")
        CfUtils.GetCf(AutoIds.IdSetting6186, "DreamAdventuresQuestPlotVo")
        
        self:InitHandler()
        self:InitData()
        self:InitBGM()
        while self._isWaiting do
            coroutine.yield(Yielders.EndOfFrame)
        end
    end))
    return coWait
end

