    SetButtonAction(self.BtnProgressBar, Bind(self, self.BtnPreparationOnClickHandler))
    SetButtonAction(self.BtnTitle, Bind(self, self.BtnTitleOnClickHandler))
    SetButtonAction(self.BtnDesc, Bind(self, self.BtnDescOnClickHandler))
    for i = 1, RoleNum do
        local btn = self['BtnRole' .. i]
        if isNotNull(btn) then
            SetButtonAction(btn, function()
                self:ShowClickDialogue(i)
            end)
        end
    end
end

