function DreamAdventuresMainDialog:BtnFightOnClickHandler()
    if not DreamAdventuresMgr:CheckActive() then return end
    
    if not DreamAdventuresMgr:CheckEntryBtnUnlock(DreamAdventuresConstants.EntryBtnType.CHAOTIC_RECALL) then
        local conf = DreamAdventuresMgr:GetEntryBtnConf(DreamAdventuresConstants.EntryBtnType.CHAOTIC_RECALL)
        local questVo = QuestConfMgr:GetInstance():GetQuestVoById(conf.unlockLevel)
        GameUtils.Toast(localize("请先通关前置关卡_name_",{_name_ = questVo.name}))
        return
    end
    
    local activityId = DreamAdventuresMgr:GetActivityId()
    local contentId = DreamAdventuresMgr:GetActivityContentId()
    local activityDojo = DreamAdventuresMgr:GetActivityDojo()
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIActivityFoodAnnihilationEntryDialog, parameters = {activityType = activityDojo.type, activityId = contentId, activityUuid = activityId, activityPrefabId = activityDojo.prefab}},
            {UIArgs(Constants.UITypeIds.ActivityDreamAdventuresMain)})
end

