---检查序章
function DreamAdventuresMainDialog:CheckPrologue()
    local activityId = DreamAdventuresMgr:GetActivityId()
    local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerId = playerComp.playerDojo.playerId
    local key = string.format('DreamAdventuresPrologue%s%s', activityId, playerId)
    local value = CfUtils.GetLocalData(key, 0)
    if checkInt(value) > 0 then return end
    
    CfUtils.WriteLocalData(key, 1)
    local storyId = DreamAdventuresMgr:GetPrologueStoryId()
    DreamAdventuresMgr:PlayingPlot({ storyId })
end

---刷新按钮状态
function DreamAdventuresMainDialog:RefreshBtnState()
    -- 商店
    local storeConf = DreamAdventuresMgr:GetEntryBtnConf(DreamAdventuresConstants.EntryBtnType.STORE)
    CfUtils.FillText(self.BtnShopText, storeConf.name)
    
    -- 任务
    local taskConf = DreamAdventuresMgr:GetEntryBtnConf(DreamAdventuresConstants.EntryBtnType.TASK)
    CfUtils.FillText(self.BtnTaskText, taskConf.name)
    
    -- 筹备
    local preparationConf = DreamAdventuresMgr:GetEntryBtnConf(DreamAdventuresConstants.EntryBtnType.PREPARATION)
    CfUtils.FillText(self.BtnProgressBarText, preparationConf.name)
    
    -- 地图
    local mapConf = DreamAdventuresMgr:GetEntryBtnConf(DreamAdventuresConstants.EntryBtnType.PLOT)
    CfUtils.FillText(self.BtnMapText, mapConf.name)
    local isMapUnlock = DreamAdventuresMgr:CheckEntryBtnUnlock(DreamAdventuresConstants.EntryBtnType.PLOT)
    CfUtils.SetUISwitchImage(self.BtnMapIcon, isMapUnlock and 1 or 2)
    CfUtils.SetActive(self.BtnMapUIFX, isMapUnlock)
    
    -- 战斗
    local fightConf = DreamAdventuresMgr:GetEntryBtnConf(DreamAdventuresConstants.EntryBtnType.CHAOTIC_RECALL)
    CfUtils.FillText(self.BtnFightText, fightConf.name)
    local isFightUnlock = DreamAdventuresMgr:CheckEntryBtnUnlock(DreamAdventuresConstants.EntryBtnType.CHAOTIC_RECALL)
    CfUtils.SetUISwitchImage(self.BtnFightIcon, isFightUnlock and 1 or 2)
    CfUtils.SetActive(self.BtnFightUIFX, isFightUnlock)

    if not DreamAdventuresMgr:IsActive() then
        CfUtils.SetUISwitchImage(self.BtnMapIcon, 2)
        CfUtils.SetUISwitchImage(self.BtnFightIcon, 2)
        CfUtils.SetActive(self.BtnProgressBarUIFX, false)
        CfUtils.SetActive(self.BtnMapUIFX, false)
        CfUtils.SetActive(self.BtnFightUIFX, false)
    end
end

---刷新活动时间
function DreamAdventuresMainDialog:RefreshActivityTime()
    local activityDojo = DreamAdventuresMgr:GetActivityDojo()
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(activityDojo.startTime, activityDojo.endTime))
    local seconds = activityDojo.closeTime - GameUtils.GetServerTime()
    if seconds > 0 then
        CfUtils.SetActive(self.BtnShopImgCutTimeBg, true)
        CfUtils.FillText(self.BtnShopTextTime, CfUtils.GetTimeHMS12(seconds))
    else
        CfUtils.SetActive(self.BtnShopImgCutTimeBg, false)
    end
end

