        self:RandomRoleStatus()
    end
    self:RefreshRoleNode()
    self:ShowGreetingDialogue()
end

---随机角色状态
function DreamAdventuresMainDialog:RandomRoleStatus()
    local contentId = DreamAdventuresMgr:GetActivityContentId()
    local vo = CfUtils.GetCf(AutoIds.IdSetting6185, 'DreamAdventuresMainStatusVo', true)
    local statusList = {}
    for _, v in ipairs(vo) do
        if contentId == checkInt(v.activityId) then
            table.insert(statusList, v)
        end
    end
    local statusConf = statusList[math.random(1, #statusList)]
    
    local roleNodeConf = {}
    for _, v in ipairs(statusConf.nodeIds) do
        local nodeVo = CfUtils.GetCfVo(AutoIds.IdSetting6183, "DreamAdventuresMainNodeVo", v)
        if nodeVo then
            table.insert(roleNodeConf, nodeVo)
        end
    end
    DreamAdventuresMgr:SetRoleNodeConf(roleNodeConf)

    local setting = CfUtils.GetCf(AutoIds.IdSetting6184, "DreamAdventuresMainLinesVo")
    local clickLinesConf = {}
    for i, v in ipairs(statusConf.touchLineIds) do
        local tmp = {}
        for _, id in ipairs(v) do
            local a = setting:Get(id)
            if setting:Get(id) then
                table.insert(tmp, setting:Get(id))
            end
        end
        clickLinesConf[roleNodeConf[i].id] = tmp
    end
    DreamAdventuresMgr:SetClickLinesConf(clickLinesConf)
    
    local greetingLinesConf = {}
    for _, v in ipairs(statusConf.greetingLineIds) do
        if setting:Get(v) then
            table.insert(greetingLinesConf, setting:Get(v))
        end
    end
    DreamAdventuresMgr:SetGreetingLinesConf(greetingLinesConf)
    
    self._parameters.random = false
    self.controller.Argument.parameters = self._parameters
end

---刷新角色节点
function DreamAdventuresMainDialog:RefreshRoleNode()
    for i = 1, RoleNum do
        local node = self['BtnRole' .. i]
        if isNotNull(node) then
            CfUtils.SetActive(node, false)
        end
    end
    
    local nodeConf = DreamAdventuresMgr:GetRoleNodeConf()
    for _, v in ipairs(nodeConf) do
        local name = string.gsub(v.node, '_', '')
        local node = self['Btn' .. name]
        if isNotNull(node) then
            CfUtils.SetActive(node, true)
        end
        if v.action then
            local spineGo = node:Find('SpineRoot/' .. v.node)
            if isNotNull(spineGo) then
                --CfUtils.PlaySpine(spineGo, v.action, true)
            end
        end
    end
end

---显示问候对话
function DreamAdventuresMainDialog:ShowGreetingDialogue()
    CfUtils.SetActive(self.DialogueRoot, true)
    local lines = DreamAdventuresMgr:GetGreetingLinesConf()
    local conf = lines[math.random(1, #lines)]
    CfUtils.FillText(self.TextName, conf.name)
    CfUtils.FillText(self.TextDialogue, conf.desc)
    if conf.voicecode then
        CriWareUtils.PlayVoiceById(conf.voicecode)
    end
    -- 重置
    self:SetClickLineId(0)
end

---显示点击对话
function DreamAdventuresMainDialog:ShowClickDialogue(index)
    local nodeVo = CfUtils.GetCf(AutoIds.IdSetting6183, "DreamAdventuresMainNodeVo", true)
    local nodeId = nil
    for _, v in ipairs(nodeVo) do
        if v.node == 'Role_' .. index then
            nodeId = v.id
            break
        end
    end
    if not nodeId then return end
    
    local lines = clone(DreamAdventuresMgr:GetClickLinesConf()[nodeId])
    local id = self:GetClickLineId()
    local conf = nil
    if #lines == 1 then
        conf = lines[1]
    else
        for i, v in ipairs(lines) do
            if checkInt(v.id) == id then
                table.remove(lines, i)
                break
            end
        end
        conf = lines[math.random(1, #lines)]
    end
    if not conf then return end

    CfUtils.FillText(self.TextName, conf.name)
    CfUtils.FillText(self.TextDialogue, conf.desc)
    if conf.voicecode then
        CriWareUtils.PlayVoiceById(conf.voicecode)
    end
    self:SetClickLineId(conf.id)
end

---刷新进度按钮
function DreamAdventuresMainDialog:RefreshBtnProgressBar()
    local allPercent = DreamAdventuresMgr:GetAllRewardsPercentage()
    self.BtnProgressBarImgFill.fillAmount = allPercent
    CfUtils.SetActive(self.TextComplete, allPercent >= 1)
    CfUtils.FillText(self.BtnProgressBarAllTextNum, string.format('%s%%', math.floor(allPercent * 1000) / 10))
    local rewardsList = DreamAdventuresMgr:GetPersonalRewardsList()
    local point = DreamAdventuresMgr:GetSelfWinePress()
    local targetPoint = checkInt(rewardsList[#rewardsList].point)
    CfUtils.FillText(self.BtnProgressBarPlayerTextNum, string.format('%d/%d', math.min(point, targetPoint), targetPoint))
end

---刷新按钮红点
function DreamAdventuresMainDialog:RefreshBtnRedPoint()
    if not DreamAdventuresMgr:IsActive() then
        CfUtils.SetActive(self.BtnProgressBarRedPoint, false)
        CfUtils.SetActive(self.BtnMapRedPoint, false)
        CfUtils.SetActive(self.BtnFightRedPoint, false)
        CfUtils.SetActive(self.BtnTaskRedPoint, false)
        CfUtils.SetActive(self.BtnShopRedPoint, false)
        return
    end
    
    -- 筹备
    local preRedState = DreamAdventuresMgr:GetPreparationRedPointState()
    if preRedState == 0 then
        CfUtils.SetActive(self.BtnProgressBarRedPoint, false)
    else
        CfUtils.SetActive(self.BtnProgressBarRedPoint, true)
        CfUtils.SetUISwitchImage(self.BtnProgressBarRedPointIcon, preRedState)
    end
    
    -- 地图
    CfUtils.SetActive(self.BtnMapRedPoint, DreamAdventuresMgr:GetMapRedPointState())
    
    -- 战斗
    CfUtils.SetActive(self.BtnFightRedPoint, DreamAdventuresMgr:GetFightRedPointState())


    -- 任务
    CfUtils.SetActive(self.BtnTaskRedPoint, DreamAdventuresMgr:GetTaskTips(1) == 0)

    -- 任务
    CfUtils.SetActive(self.BtnShopRedPoint, DreamAdventuresMgr:GetTaskTips(2) == 0)
end
